(() => {
'use strict';
const products=window.TOP_PRODUCTS||[], key='top-solutions-cart-v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('pt-MZ',{style:'currency',currency:'MZN'}).format(n);
const known=p=>typeof p.price==='number'&&Number.isFinite(p.price)&&p.price>=0;
const price=p=>known(p)?money(p.price):'Preço sob consulta';
const url=p=>'produto.html?id='+encodeURIComponent(p.id);
const whatsapp=text=>'https://wa.me/258837860064?text='+encodeURIComponent(text);
let cart=[], storageAvailable=true;
try { const data=JSON.parse(localStorage.getItem(key)||'[]'); if(Array.isArray(data)) for(const row of data) {if(row&&products.some(p=>p.id===row.id)&&Number.isInteger(row.quantity)&&row.quantity>0&&!cart.some(r=>r.id===row.id))cart.push({id:row.id,quantity:Math.min(99,row.quantity)});}}catch {storageAvailable=false;}
const status=document.createElement('p');status.className='shop-status';status.setAttribute('role','status');document.body.append(status);
function save(){try{localStorage.setItem(key,JSON.stringify(cart));}catch{storageAvailable=false;}count();}
function count(){document.querySelectorAll('[data-cart-count]').forEach(el=>el.textContent=cart.reduce((n,r)=>n+r.quantity,0));}
function images(p){return [...new Set([p.image,...(Array.isArray(p.images)?p.images:[])].filter(s=>typeof s==='string'&&s.trim()))];}
function image(p,src){return src?`<img class="product-image" src="${esc(src)}" alt="${esc(p.name)}">`:'<div class="image-placeholder"><svg class="icon" aria-hidden="true"><use href="#i-image"/></svg><span>Fotografias em breve</span></div>';}
function message(rows){return 'Olá, Top Solutions! Gostaria de comprar:\n\n'+rows.map(r=>{const p=products.find(p=>p.id===r.id);return `${p.name}\nReferência: ${p.id}\nQuantidade: ${r.quantity}\nPreço unitário: ${price(p)}${known(p)?'\nSubtotal: '+money(p.price*r.quantity):''}\n${new URL(url(p),location.href).href}`;}).join('\n\n')+'\n\n'+summary(rows)+'\nPor favor, confirmem disponibilidade, valor final, entrega e formas de pagamento.';}
function summary(rows){let total=0,unknown=false;rows.forEach(r=>{const p=products.find(p=>p.id===r.id);if(known(p))total+=p.price*r.quantity;else unknown=true;});return unknown?(total?'Subtotal dos produtos com preço: '+money(total)+'. Outros preços sob consulta.':'Total sob consulta.'):'Subtotal: '+money(total);}
const productPage=document.querySelector('#product-page');
if(productPage){const p=products.find(p=>p.id===new URLSearchParams(location.search).get('id'));if(!p){document.title='Produto não encontrado — Top Solutions';productPage.innerHTML='<h1>Produto não encontrado.</h1><p>Este produto não está disponível no catálogo.</p><a class="button button-blue" href="index.html#produtos">Explorar catálogo</a>';}else{document.title=p.name+' — Top Solutions';const photos=images(p);productPage.innerHTML=`<a class="text-link" href="index.html#produtos">← Voltar ao catálogo</a><div class="product-layout"><div><div class="gallery-main" id="gallery-main">${image(p,photos[0])}</div><div class="gallery-thumbs">${photos.map((src,i)=>`<button data-photo="${i}" aria-label="Ver imagem ${i+1} de ${esc(p.name)}" aria-pressed="${i===0}">${image(p,src)}</button>`).join('')}</div></div><div class="product-copy"><span class="eyebrow section-kicker">${esc(p.category)}</span><h1>${esc(p.name)}</h1><p class="product-price">${price(p)}</p><h2>Descrição do produto</h2><p class="lead">${esc(p.description)}</p><p class="reference">Referência: ${esc(p.id)}</p><div class="purchase-actions"><a class="button button-whatsapp" href="${esc(whatsapp(message([{id:p.id,quantity:1}])))}">Comprar no WhatsApp</a><button class="button button-dark" data-add="${esc(p.id)}">Adicionar ao carrinho</button><a class="text-link" href="carrinho.html">Ver carrinho →</a></div><p class="sample-note">${window.TOP_CONTENT?.sampleCatalogue ? 'Produto ilustrativo. ' : ''}Confirme modelo, preço e disponibilidade antes de comprar.</p><a class="text-link" href="politicas.html">Entrega, devoluções e garantias →</a></div></div>`;productPage.addEventListener('click',e=>{const b=e.target.closest('[data-photo]');if(!b)return;document.querySelector('#gallery-main').innerHTML=image(p,photos[Number(b.dataset.photo)]);document.querySelectorAll('[data-photo]').forEach(el=>el.setAttribute('aria-pressed',el===b));});}}
const cartPage=document.querySelector('#cart-page');
function renderCart(){if(!cartPage)return;if(!cart.length){cartPage.innerHTML='<div class="content-panel"><h2>O seu carrinho está vazio.</h2><p>Explore o catálogo e adicione os produtos que procura.</p><a class="button button-blue" href="index.html#produtos">Descobrir produtos</a></div>';return;}
cartPage.innerHTML=`<div class="cart-layout"><div>${cart.map(r=>{const p=products.find(p=>p.id===r.id);return `<article class="cart-row"><a class="cart-image" href="${url(p)}">${image(p,images(p)[0])}</a><div><a href="${url(p)}"><h2>${esc(p.name)}</h2></a><p>${price(p)}</p><div class="quantity-control"><button data-change="-1" data-id="${esc(p.id)}" aria-label="Diminuir quantidade de ${esc(p.name)}" ${r.quantity===1?'disabled':''}>−</button><span aria-label="Quantidade">${r.quantity}</span><button data-change="1" data-id="${esc(p.id)}" aria-label="Aumentar quantidade de ${esc(p.name)}" ${r.quantity===99?'disabled':''}>+</button><button class="remove-item" data-remove="${esc(p.id)}">Remover</button></div></div></article>`;}).join('')}</div><aside class="cart-summary"><h2>Resumo do pedido</h2><p>${esc(summary(cart))}</p><p>Entrega e valor final a confirmar no WhatsApp. O pedido fica sujeito à confirmação da equipa.</p><a class="button button-whatsapp" href="${esc(whatsapp(message(cart)))}">Finalizar no WhatsApp</a><a class="text-link" href="index.html#produtos">Continuar a comprar →</a><a class="text-link" href="politicas.html">Consultar políticas</a>${!storageAvailable?'<p>O armazenamento está indisponível. O carrinho poderá perder-se ao mudar de página.</p>':''}</aside></div>`;
}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add){const p=products.find(p=>p.id===add.dataset.add);if(!p)return;let row=cart.find(r=>r.id===p.id);if(row&&row.quantity===99){status.textContent='Limite de 99 unidades por produto.';return;}if(row)row.quantity++;else cart.push({id:p.id,quantity:1});save();status.textContent=p.name+' adicionado ao carrinho.'+(!storageAvailable?' O navegador não permite guardar o carrinho.':'');}
const change=e.target.closest('[data-change]'),remove=e.target.closest('[data-remove]');if(change){const row=cart.find(r=>r.id===change.dataset.id);if(row){row.quantity=Math.max(1,Math.min(99,row.quantity+Number(change.dataset.change)));save();renderCart();const replacement=[...document.querySelectorAll('[data-change]')].find(b=>b.dataset.id===change.dataset.id&&b.dataset.change===change.dataset.change);replacement?.focus();status.textContent='Quantidade actualizada: '+row.quantity;}}if(remove){cart=cart.filter(r=>r.id!==remove.dataset.remove);save();renderCart();status.textContent='Produto removido do carrinho.';cartPage.querySelector('button,a')?.focus();}});
document.addEventListener('error',e=>{if(e.target.matches?.('img.product-image')){e.target.outerHTML='<div class="image-placeholder"><span>Imagem indisponível</span></div>';}},true);
window.addEventListener('storage',e=>{if(e.key===key)location.reload();});
count();renderCart();const year=document.querySelector('#year');if(year)year.textContent=new Date().getFullYear();
})();
